<?php require_once __DIR__.'/../config/functions.php'; if(is_admin())go('/admin/index.php');$pageTitle='Admin login';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$email=trim($_POST['email']??'');$password=$_POST['password']??'';$q=$pdo->prepare("SELECT * FROM users WHERE email=? AND role='admin' LIMIT 1");$q->execute([$email]);$u=$q->fetch();if($u&&password_verify($password,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=(int)$u['id'];$_SESSION['user_name']=$u['name'];$_SESSION['role']='admin';go('/admin/index.php');}else $error='Invalid administrator credentials.';}
include __DIR__.'/../includes/header.php'; ?>
<section class="auth-section"><div class="auth-card"><h2>Administrator login</h2><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Email</label><input class="form-control mb-3" type="email" name="email" required><label>Password</label><input class="form-control mb-3" type="password" name="password" required><button class="btn btn-accent w-100">Sign in to dashboard</button></form><p class="small muted mt-3">Run setup_admin.php once after importing the database to create the first admin.</p></div></section>
